insert into public.lesson_meta (id, meta) values ($cdm$ethhack-ethics$cdm$, $cdm${"title":"Hacking with permission: ethics, law and scope","kind":"read","task":null,"hint":null,"body":"## The one rule\n\nAn **ethical hacker** (penetration tester, \"pentester\", red teamer) attacks systems **with the owner's written permission**, inside an agreed **scope**, to find weaknesses **before criminals do**, and reports them so they get fixed. Without permission the same actions are a crime, however good your intentions.\n\n- In Nigeria, the **Cybercrimes (Prohibition, Prevention, etc.) Act 2015** (amended 2024) makes unauthorised access to a computer system an offence, with fines and prison terms.\n- The UK's Computer Misuse Act, the US Computer Fraud and Abuse Act and similar laws elsewhere say the same.\n- \"I was only looking\", \"it was not protected\" or \"I wanted to help\" are not defences.\n\n## What permission looks like\n\nBefore any test, professionals sign:\n\n1. **A contract or statement of work** with the system owner (not just an employee who says \"go ahead\")\n2. **Scope**: exactly which systems are in (these web addresses, these IP ranges, this app) and which are **out** (third-party services, other customers, payment processors)\n3. **Rules of engagement**: dates and times, what is allowed (no denial of service, no social engineering of staff unless agreed), how to handle real customer data you see, and who to call in an emergency\n4. **A safe harbour / authorisation letter** you can show if anyone asks\n\nIf you find something outside scope, **stop and ask**. If a system belongs to someone else (a hosting company, a cloud provider), their permission matters too; most cloud providers publish rules for testing what you host with them.\n\n## Bug bounties and disclosure\n\nMany companies run **bug bounty programmes** (HackerOne, Bugcrowd, Intigriti, their own pages) that give public permission to test **specific** things under **specific** rules, and pay for valid findings. Read the policy every time: it is your permission and its limits.\n\nIf you stumble on a weakness with no programme, use **responsible (coordinated) disclosure**: report privately to the owner, give them reasonable time to fix (often 90 days), and never use or publish the weakness or the data first.\n\n## The ethics beyond the law\n\n- Do the minimum needed to prove a finding. Do not download, keep or look through more personal data than you must.\n- Never damage, change or delete real data.\n- Keep findings confidential; the report is for the client.\n- Tell the truth in your report, including what you could not test.\n\nThis course teaches the defender's understanding of attacks: how testers work, how to read their results, how weaknesses are found and fixed. Practise only on systems you own or on legal training labs.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":false,"order":0}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-method$cdm$, $cdm${"title":"How a penetration test works","kind":"read","task":null,"hint":null,"body":"## The phases\n\nEvery professional methodology (PTES, OWASP Web Security Testing Guide, NIST SP 800-115) follows the same shape:\n\n1. **Planning and scoping**: goals, scope, rules, contacts (lesson 1).\n2. **Reconnaissance (information gathering)**: what does the target expose? Web addresses, sub-domains, technologies, public documents, staff roles. *Passive* recon uses public information only; *active* recon touches the target (allowed only in scope).\n3. **Scanning and enumeration**: which services are running, which versions, which pages and inputs exist.\n4. **Vulnerability analysis**: which of those could be weak? Outdated software with known issues (CVEs), weak settings, missing checks on inputs or permissions.\n5. **Exploitation (proof)**: carefully demonstrating that a weakness is real and what it allows, with the least possible impact.\n6. **Post-exploitation**: within the rules, what could an attacker reach from there? Often stops at a screenshot as proof.\n7. **Reporting**: clear findings, evidence, risk rating, and how to fix each one. **The report is the product.**\n8. **Retest**: check the fixes work.\n\n## Kinds of tests\n\n- **Black box**: the tester starts with almost nothing, like an outside attacker.\n- **Grey box**: some knowledge or a normal user account (most common for web apps).\n- **White box**: full information, including source code; finds the most per hour.\n- **Red team**: a long, stealthy exercise testing people, processes and detection, not just technology.\n- **Vulnerability assessment**: wide scanning and listing of weaknesses without exploiting them.\n\n## The OWASP Top 10\n\nThe best-known list of web application risks (2021 edition): broken access control, cryptographic failures, injection, insecure design, security misconfiguration, vulnerable and outdated components, identification and authentication failures, software and data integrity failures, security logging and monitoring failures, and server-side request forgery. You met several in Cybersecurity essentials; this course goes deeper on finding, rating and reporting them.\n\n## Your practice lab (legal and free)\n\n- **TryHackMe** and **Hack The Box**: guided rooms and machines you are allowed to attack\n- **OWASP Juice Shop**, **DVWA** and **WebGoat**: deliberately vulnerable web apps to run on your own computer\n- **PortSwigger Web Security Academy**: free web security labs\n- **picoCTF** and other Capture the Flag (CTF) games\n- Common tools you will meet there: Nmap (scanning), Burp Suite or OWASP ZAP (web proxies), Wireshark (traffic), and the Kali Linux distribution, which bundles many tools.\n\nNever point tools at systems outside these labs or your written scope.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":false,"order":1}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-recon$cdm$, $cdm${"title":"Reading scan results like a tester","kind":"code","task":"Write parseScan, openServices and flags.","hint":"parseScan: text.split('\\n').map(l => l.trim()).filter(l => /^\\d+\\/(tcp|udp)\\s/.test(l)).map(l => { const [pp, state, service, ...rest] = l.split(/\\s+/); const [port, proto] = pp.split('/'); return { port: Number(port), proto, state, service, version: rest.join(' ') } })","body":"## From a scan to a picture of the target\n\nAfter scanning an **in-scope** host, a tester gets lines like these (a simplified version of what tools such as Nmap print):\n\n```text\n21/tcp   open     ftp       vsftpd 2.3.4\n22/tcp   open     ssh       OpenSSH 8.9\n23/tcp   open     telnet\n80/tcp   open     http      nginx 1.18.0\n443/tcp  open     https     nginx 1.18.0\n3306/tcp filtered mysql\n3389/tcp closed   ms-wbt-server\n```\n\n- **open**: something answers on that port.\n- **closed**: nothing listens there.\n- **filtered**: a firewall stops the probe, so the state is unknown.\n\nThe skill is **judgement**: which open services should not be reachable from the internet, or are old?\n\n## Red flags\n\n- **Plain-text protocols**: telnet (23) and FTP (21) send passwords unencrypted. Use SSH and SFTP instead.\n- **Databases and admin services on the internet**: MySQL (3306), PostgreSQL (5432), MongoDB (27017), Redis (6379), remote desktop (3389) should sit behind a firewall or VPN.\n- **Old versions**: a version number lets you look up known vulnerabilities (CVEs) in public databases such as NVD. Old software is one of the commonest real findings.\n\nDefenders run the same checks on their own systems: \"attack surface management\".\n\n## Your task\n\n1. `parseScan(text)`: return an array of `{ port, proto, state, service, version }` for every line that starts with a port like `22/tcp`. `port` is a number; `version` is the rest of the line after the service (trimmed), or `''`.\n2. `openServices(rows)`: only the rows whose state is `'open'`.\n3. `flags(rows)`: for each **open** row, return a message when it is risky:\n   - service `telnet` or `ftp`: `\"PORT SERVICE: sends passwords unencrypted\"`\n   - port in `RISKY_EXPOSED`: `\"PORT SERVICE: should not be reachable from the internet\"`\n   (Check unencrypted first; one message per row at most.)","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":2}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-recon$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-recon","title":"Reading scan results like a tester","minutes":25,"kind":"code","outline":"Turn raw service-scan output into a list of exposed services and flag the risky ones.","body":"## From a scan to a picture of the target\n\nAfter scanning an **in-scope** host, a tester gets lines like these (a simplified version of what tools such as Nmap print):\n\n```text\n21/tcp   open     ftp       vsftpd 2.3.4\n22/tcp   open     ssh       OpenSSH 8.9\n23/tcp   open     telnet\n80/tcp   open     http      nginx 1.18.0\n443/tcp  open     https     nginx 1.18.0\n3306/tcp filtered mysql\n3389/tcp closed   ms-wbt-server\n```\n\n- **open**: something answers on that port.\n- **closed**: nothing listens there.\n- **filtered**: a firewall stops the probe, so the state is unknown.\n\nThe skill is **judgement**: which open services should not be reachable from the internet, or are old?\n\n## Red flags\n\n- **Plain-text protocols**: telnet (23) and FTP (21) send passwords unencrypted. Use SSH and SFTP instead.\n- **Databases and admin services on the internet**: MySQL (3306), PostgreSQL (5432), MongoDB (27017), Redis (6379), remote desktop (3389) should sit behind a firewall or VPN.\n- **Old versions**: a version number lets you look up known vulnerabilities (CVEs) in public databases such as NVD. Old software is one of the commonest real findings.\n\nDefenders run the same checks on their own systems: \"attack surface management\".\n\n## Your task\n\n1. `parseScan(text)`: return an array of `{ port, proto, state, service, version }` for every line that starts with a port like `22/tcp`. `port` is a number; `version` is the rest of the line after the service (trimmed), or `''`.\n2. `openServices(rows)`: only the rows whose state is `'open'`.\n3. `flags(rows)`: for each **open** row, return a message when it is risky:\n   - service `telnet` or `ftp`: `\"PORT SERVICE: sends passwords unencrypted\"`\n   - port in `RISKY_EXPOSED`: `\"PORT SERVICE: should not be reachable from the internet\"`\n   (Check unencrypted first; one message per row at most.)","task":"Write parseScan, openServices and flags.","starter":"<script>\n  const RISKY_EXPOSED = [3306, 5432, 27017, 6379, 3389, 445]\n  const SCAN = `Starting scan of 192.0.2.10 (in scope: test-server)\n21/tcp   open     ftp       vsftpd 2.3.4\n22/tcp   open     ssh       OpenSSH 8.9\n23/tcp   open     telnet\n80/tcp   open     http      nginx 1.18.0\n3306/tcp open     mysql     MySQL 5.5.62\n3389/tcp closed   ms-wbt-server\n5432/tcp filtered postgresql\nScan done`\n\n  function parseScan(text) {\n  }\n  function openServices(rows) {\n  }\n  function flags(rows) {\n  }\n</script>\n","checks":[{"label":"parses every port line","test":"const r = parseScan(SCAN); return r.length === 7 && r[0].port === 21 && r[0].proto === 'tcp' && r[0].service === 'ftp' && r[0].version === 'vsftpd 2.3.4'"},{"label":"missing versions are empty text","test":"return parseScan(SCAN).find(r => r.port === 23).version === ''"},{"label":"only open services","test":"return openServices(parseScan(SCAN)).map(r => r.port).join() === '21,22,23,80,3306'"},{"label":"unencrypted logins flagged","test":"const f = flags(parseScan(SCAN)); return f.includes('21 ftp: sends passwords unencrypted') && f.includes('23 telnet: sends passwords unencrypted')"},{"label":"exposed database flagged, closed and filtered ignored","test":"const f = flags(parseScan(SCAN)); return f.includes('3306 mysql: should not be reachable from the internet') && f.length === 3"}],"hint":"parseScan: text.split('\\n').map(l => l.trim()).filter(l => /^\\d+\\/(tcp|udp)\\s/.test(l)).map(l => { const [pp, state, service, ...rest] = l.split(/\\s+/); const [port, proto] = pp.split('/'); return { port: Number(port), proto, state, service, version: rest.join(' ') } })"}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-injection$cdm$, $cdm${"title":"Injection flaws: how they happen and how they are fixed","kind":"code","task":"Write query, sortColumn and looksSuspicious.","hint":"query: const n = (sql.match(/\\?/g) || []).length; if (n !== params.length) throw new Error('wrong number of values'); let i = 0; return { text: sql.replace(/\\?/g, () => '$' + (++i)), values: [...params] }","body":"## Data that turns into commands\n\n**Injection** happens when an app builds a command (an SQL query, a shell command, an LDAP or template expression) by **gluing user input into the command text**. If the input contains the command language's special characters, it changes what the command does.\n\nA login check built like this:\n\n```js\n\"SELECT * FROM users WHERE email = '\" + email + \"' AND password_hash = '\" + hash + \"'\"\n```\n\nlets input containing a quote end the string early and add its own conditions. Testers find these by sending carefully chosen characters (a single quote, for instance) to every input and watching for errors or changed behaviour, **only in scope**.\n\n## The real fix: parameterised queries\n\nNever build commands from strings. Send the command and the data **separately**: the database treats the data purely as a value, whatever characters it contains.\n\n```js\ndb.query('SELECT * FROM users WHERE email = $1', [email])   // node-postgres\nsupabase.from('users').select().eq('email', email)           // query builders do this for you\n```\n\nAlso:\n\n- **Allow-lists** for things that cannot be parameters (column names for sorting, table names): only accept values from a fixed list.\n- **Least privilege**: the app's database account should not be able to drop tables or read other apps' data.\n- **Do not show database errors** to users; log them on the server.\n- \"Escaping\" or blocking bad words (blacklists) is fragile and easy to get wrong. Detection is useful for **logging and alerts**, never as the defence.\n\n## Your task\n\n1. `query(sql, params)`: a safe query **object** builder. Count the `?` placeholders in `sql`; if the number of `params` differs, throw an Error. Return `{ text, values }` where `text` has each `?` replaced by `$1`, `$2`, … (in order) and `values` is a copy of params. User data never goes into `text`.\n2. `sortColumn(input)`: return `input` if it is one of `ALLOWED_SORT`, otherwise `'created_at'`.\n3. `looksSuspicious(input)`: for **logging only**, true if the text contains a single quote followed later by `or`/`and` (any case) or contains `--`, `;` or `/*`.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":3}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-injection$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-injection","title":"Injection flaws: how they happen and how they are fixed","minutes":30,"kind":"code","outline":"Why mixing data into commands is dangerous, and build the fix: parameterised queries and allow-lists.","body":"## Data that turns into commands\n\n**Injection** happens when an app builds a command (an SQL query, a shell command, an LDAP or template expression) by **gluing user input into the command text**. If the input contains the command language's special characters, it changes what the command does.\n\nA login check built like this:\n\n```js\n\"SELECT * FROM users WHERE email = '\" + email + \"' AND password_hash = '\" + hash + \"'\"\n```\n\nlets input containing a quote end the string early and add its own conditions. Testers find these by sending carefully chosen characters (a single quote, for instance) to every input and watching for errors or changed behaviour, **only in scope**.\n\n## The real fix: parameterised queries\n\nNever build commands from strings. Send the command and the data **separately**: the database treats the data purely as a value, whatever characters it contains.\n\n```js\ndb.query('SELECT * FROM users WHERE email = $1', [email])   // node-postgres\nsupabase.from('users').select().eq('email', email)           // query builders do this for you\n```\n\nAlso:\n\n- **Allow-lists** for things that cannot be parameters (column names for sorting, table names): only accept values from a fixed list.\n- **Least privilege**: the app's database account should not be able to drop tables or read other apps' data.\n- **Do not show database errors** to users; log them on the server.\n- \"Escaping\" or blocking bad words (blacklists) is fragile and easy to get wrong. Detection is useful for **logging and alerts**, never as the defence.\n\n## Your task\n\n1. `query(sql, params)`: a safe query **object** builder. Count the `?` placeholders in `sql`; if the number of `params` differs, throw an Error. Return `{ text, values }` where `text` has each `?` replaced by `$1`, `$2`, … (in order) and `values` is a copy of params. User data never goes into `text`.\n2. `sortColumn(input)`: return `input` if it is one of `ALLOWED_SORT`, otherwise `'created_at'`.\n3. `looksSuspicious(input)`: for **logging only**, true if the text contains a single quote followed later by `or`/`and` (any case) or contains `--`, `;` or `/*`.","task":"Write query, sortColumn and looksSuspicious.","starter":"<script>\n  const ALLOWED_SORT = ['created_at', 'name', 'price', 'stock']\n\n  function query(sql, params) {\n  }\n  function sortColumn(input) {\n  }\n  function looksSuspicious(input) {\n  }\n</script>\n","checks":[{"label":"placeholders become $1, $2","test":"const q = query('SELECT * FROM users WHERE email = ? AND active = ?', ['a@b.ng', true]); return q.text === 'SELECT * FROM users WHERE email = $1 AND active = $2' && q.values[0] === 'a@b.ng'"},{"label":"input never enters the query text","test":"const evil = \"x' OR '1'='1\"; const q = query('SELECT * FROM users WHERE email = ?', [evil]); return !q.text.includes(evil) && q.values[0] === evil"},{"label":"wrong number of values is refused","test":"try { query('SELECT ? , ?', [1]); return false } catch { return true }"},{"label":"values are copied","test":"const p = [1]; const q = query('SELECT ?', p); p.push(2); return q.values.length === 1"},{"label":"sort columns come from an allow-list","test":"return sortColumn('price') === 'price' && sortColumn('price; DROP TABLE users') === 'created_at'"},{"label":"suspicious input is noticed for the logs","test":"return looksSuspicious(\"x' or 1=1\") && looksSuspicious('a -- b') && !looksSuspicious(\"O'Neil\") && !looksSuspicious('Mama Nkechi')"}],"hint":"query: const n = (sql.match(/\\?/g) || []).length; if (n !== params.length) throw new Error('wrong number of values'); let i = 0; return { text: sql.replace(/\\?/g, () => '$' + (++i)), values: [...params] }"}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-sessions$cdm$, $cdm${"title":"Sessions and tokens: what testers check","kind":"code","task":"Write decodePart and checkClaims.","hint":"decodePart: let s = part.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; return JSON.parse(atob(s)). In checkClaims, wrap the decoding in try/catch and return ['malformed'] on failure.","body":"## Who is this request from?\n\nAfter you sign in, a web app gives your browser a **session cookie** or a **token** that proves who you are on every request. If an attacker can steal, guess, forge or reuse it, they become you. Testers check:\n\n- **Cookies**: `HttpOnly` (JavaScript cannot read it), `Secure` (only over HTTPS), `SameSite` (limits cross-site requests), sensible expiry, and a new session ID after sign-in.\n- **Sign-out** really ends the session on the server.\n- **Access control on every request**: changing an ID in the address (`/invoices/105`) must not show someone else's data (IDOR).\n- **Tokens**: especially **JSON Web Tokens (JWTs)**.\n\n## JWTs in one minute\n\nA JWT has three parts separated by dots: `header.payload.signature`, each **base64url**-encoded. The header says which algorithm signed it (`alg`), the payload holds **claims** such as `sub` (user), `exp` (expiry, in seconds since 1970), `iss` (issuer) and `aud` (audience). The signature proves the server made it.\n\n**Anyone can decode** a JWT: it is signed, not secret. Never put passwords or private data in it.\n\nClassic mistakes testers look for (and servers must prevent):\n\n- Accepting `\"alg\": \"none\"` (no signature at all)\n- Not checking `exp`, so stolen tokens work forever\n- Not checking `iss` and `aud`, so a token for another app is accepted\n- Weak signing secrets that can be guessed\n- Trusting claims like `\"role\": \"admin\"` without verifying the signature first\n\n## Your task\n\n1. `decodePart(part)`: base64url → text → JSON. (base64url uses `-` and `_` instead of `+` and `/`, and may drop the `=` padding; `atob` needs standard base64.)\n2. `checkClaims(token, now, expected)`: **after** a real signature check (done elsewhere by a library), apply the claim rules. Return a list of problems (empty if fine):\n   - `'alg none not allowed'` if the header's `alg` is `none` (any case)\n   - `'expired'` if `exp` is missing or `exp <= now` (`now` in seconds)\n   - `'wrong issuer'` if `iss !== expected.iss`\n   - `'wrong audience'` if `aud` (a string or an array) does not include `expected.aud`\n   - `'malformed'` (only this) if the token does not have 3 parts or cannot be decoded.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":4}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-sessions$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-sessions","title":"Sessions and tokens: what testers check","minutes":30,"kind":"code","outline":"How sign-in tokens work, common token mistakes, and write the checks a server must make on a JWT.","body":"## Who is this request from?\n\nAfter you sign in, a web app gives your browser a **session cookie** or a **token** that proves who you are on every request. If an attacker can steal, guess, forge or reuse it, they become you. Testers check:\n\n- **Cookies**: `HttpOnly` (JavaScript cannot read it), `Secure` (only over HTTPS), `SameSite` (limits cross-site requests), sensible expiry, and a new session ID after sign-in.\n- **Sign-out** really ends the session on the server.\n- **Access control on every request**: changing an ID in the address (`/invoices/105`) must not show someone else's data (IDOR).\n- **Tokens**: especially **JSON Web Tokens (JWTs)**.\n\n## JWTs in one minute\n\nA JWT has three parts separated by dots: `header.payload.signature`, each **base64url**-encoded. The header says which algorithm signed it (`alg`), the payload holds **claims** such as `sub` (user), `exp` (expiry, in seconds since 1970), `iss` (issuer) and `aud` (audience). The signature proves the server made it.\n\n**Anyone can decode** a JWT: it is signed, not secret. Never put passwords or private data in it.\n\nClassic mistakes testers look for (and servers must prevent):\n\n- Accepting `\"alg\": \"none\"` (no signature at all)\n- Not checking `exp`, so stolen tokens work forever\n- Not checking `iss` and `aud`, so a token for another app is accepted\n- Weak signing secrets that can be guessed\n- Trusting claims like `\"role\": \"admin\"` without verifying the signature first\n\n## Your task\n\n1. `decodePart(part)`: base64url → text → JSON. (base64url uses `-` and `_` instead of `+` and `/`, and may drop the `=` padding; `atob` needs standard base64.)\n2. `checkClaims(token, now, expected)`: **after** a real signature check (done elsewhere by a library), apply the claim rules. Return a list of problems (empty if fine):\n   - `'alg none not allowed'` if the header's `alg` is `none` (any case)\n   - `'expired'` if `exp` is missing or `exp <= now` (`now` in seconds)\n   - `'wrong issuer'` if `iss !== expected.iss`\n   - `'wrong audience'` if `aud` (a string or an array) does not include `expected.aud`\n   - `'malformed'` (only this) if the token does not have 3 parts or cannot be decoded.","task":"Write decodePart and checkClaims.","starter":"<script>\n  // makes test tokens (unsigned: the signature check is a library's job; we check the claims)\n  const b64u = (o) => btoa(JSON.stringify(o)).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '')\n  const make = (h, p) => b64u(h) + '.' + b64u(p) + '.sig'\n\n  function decodePart(part) {\n  }\n  function checkClaims(token, now, expected) {\n  }\n</script>\n","checks":[{"label":"decodes base64url without padding","test":"return decodePart(b64u({ sub: 'u1', name: 'Ada?>' })).name === 'Ada?>'"},{"label":"a good token has no problems","test":"return checkClaims(make({ alg: 'HS256' }, { iss: 'cdm', aud: 'shop', exp: 2000 }), 1000, { iss: 'cdm', aud: 'shop' }).length === 0"},{"label":"alg none is refused","test":"return checkClaims(make({ alg: 'None' }, { iss: 'cdm', aud: 'shop', exp: 2000 }), 1000, { iss: 'cdm', aud: 'shop' }).includes('alg none not allowed')"},{"label":"expired or missing exp","test":"const e = { iss: 'cdm', aud: 'shop' }; return checkClaims(make({ alg: 'HS256' }, { iss: 'cdm', aud: 'shop', exp: 1000 }), 1000, e).includes('expired') && checkClaims(make({ alg: 'HS256' }, { iss: 'cdm', aud: 'shop' }), 1, e).includes('expired')"},{"label":"issuer and audience (string or list)","test":"const e = { iss: 'cdm', aud: 'shop' }; const a = checkClaims(make({ alg: 'HS256' }, { iss: 'evil', aud: ['blog'], exp: 2000 }), 1000, e); const b = checkClaims(make({ alg: 'HS256' }, { iss: 'cdm', aud: ['blog', 'shop'], exp: 2000 }), 1000, e); return a.includes('wrong issuer') && a.includes('wrong audience') && b.length === 0"},{"label":"malformed tokens","test":"const e = { iss: 'cdm', aud: 'shop' }; return JSON.stringify(checkClaims('abc', 1, e)) === '[\"malformed\"]' && JSON.stringify(checkClaims('a.b.c', 1, e)) === '[\"malformed\"]'"}],"hint":"decodePart: let s = part.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; return JSON.parse(atob(s)). In checkClaims, wrap the decoding in try/catch and return ['malformed'] on failure."}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-risk$cdm$, $cdm${"title":"Rating and prioritising findings","kind":"code","task":"Write severity, prioritise and summary.","hint":"prioritise: [...findings].sort((a, b) => b.score - a.score || Number(b.internet) - Number(a.internet) || a.title.localeCompare(b.title)).map(f => ({ title: f.title, score: f.score, severity: severity(f.score) }))","body":"## Not every bug is an emergency\n\nA test may find 40 issues. The client needs to know **which to fix this week**. Testers rate each finding by:\n\n- **Likelihood / exploitability**: can it be reached from the internet? Does it need a login or special conditions? Is there public exploit code?\n- **Impact**: confidentiality, integrity and availability (the CIA triad): could an attacker read all customer data, change payments, or take the service down?\n\nThe industry standard is **CVSS** (Common Vulnerability Scoring System), which turns these factors into a score from **0.0 to 10.0** with severity bands:\n\n| Score | Severity |\n|---|---|\n| 0.0 | None |\n| 0.1 to 3.9 | Low |\n| 4.0 to 6.9 | Medium |\n| 7.0 to 8.9 | High |\n| 9.0 to 10.0 | Critical |\n\nContext matters: the same weakness is more urgent on an internet-facing payment page than on an internal test server. Good reports give the CVSS score **and** a plain-language business impact.\n\n## Your task\n\n1. `severity(score)`: the band name for a score (use the table; scores outside 0..10 throw an Error).\n2. `prioritise(findings)`: `findings` are `{ title, score, internet }`. Sort so that higher scores come first; for equal scores, internet-facing (`internet: true`) first; then by title A to Z. Return a new array of `{ title, score, severity }` without changing the input.\n3. `summary(findings)`: an object counting findings per severity, e.g. `{ Critical: 1, High: 2, Medium: 0, Low: 1, None: 0 }` (all five keys always present).","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":5}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-risk$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-risk","title":"Rating and prioritising findings","minutes":25,"kind":"code","outline":"Likelihood and impact, CVSS severity bands, and sort a list of findings so the worst get fixed first.","body":"## Not every bug is an emergency\n\nA test may find 40 issues. The client needs to know **which to fix this week**. Testers rate each finding by:\n\n- **Likelihood / exploitability**: can it be reached from the internet? Does it need a login or special conditions? Is there public exploit code?\n- **Impact**: confidentiality, integrity and availability (the CIA triad): could an attacker read all customer data, change payments, or take the service down?\n\nThe industry standard is **CVSS** (Common Vulnerability Scoring System), which turns these factors into a score from **0.0 to 10.0** with severity bands:\n\n| Score | Severity |\n|---|---|\n| 0.0 | None |\n| 0.1 to 3.9 | Low |\n| 4.0 to 6.9 | Medium |\n| 7.0 to 8.9 | High |\n| 9.0 to 10.0 | Critical |\n\nContext matters: the same weakness is more urgent on an internet-facing payment page than on an internal test server. Good reports give the CVSS score **and** a plain-language business impact.\n\n## Your task\n\n1. `severity(score)`: the band name for a score (use the table; scores outside 0..10 throw an Error).\n2. `prioritise(findings)`: `findings` are `{ title, score, internet }`. Sort so that higher scores come first; for equal scores, internet-facing (`internet: true`) first; then by title A to Z. Return a new array of `{ title, score, severity }` without changing the input.\n3. `summary(findings)`: an object counting findings per severity, e.g. `{ Critical: 1, High: 2, Medium: 0, Low: 1, None: 0 }` (all five keys always present).","task":"Write severity, prioritise and summary.","starter":"<script>\n  const FINDINGS = [\n    { title: 'Outdated jQuery on blog', score: 4.3, internet: true },\n    { title: 'SQL injection in login', score: 9.8, internet: true },\n    { title: 'Missing HttpOnly on session cookie', score: 5.4, internet: true },\n    { title: 'Default admin password on test server', score: 9.8, internet: false },\n    { title: 'Verbose error messages', score: 3.1, internet: true },\n  ]\n  function severity(score) {\n  }\n  function prioritise(findings) {\n  }\n  function summary(findings) {\n  }\n</script>\n","checks":[{"label":"severity bands","test":"return severity(0) === 'None' && severity(3.9) === 'Low' && severity(4) === 'Medium' && severity(7) === 'High' && severity(9) === 'Critical' && severity(10) === 'Critical'"},{"label":"scores outside 0 to 10 are refused","test":"try { severity(11); return false } catch { return true }"},{"label":"worst first, internet-facing breaks ties","test":"return prioritise(FINDINGS).map(f => f.title).slice(0, 2).join('|') === 'SQL injection in login|Default admin password on test server'"},{"label":"each row gets its severity, input unchanged","test":"const p = prioritise(FINDINGS); return p[4].severity === 'Low' && FINDINGS[0].title === 'Outdated jQuery on blog' && !('severity' in FINDINGS[0])"},{"label":"summary counts every band","test":"return JSON.stringify(summary(FINDINGS)) === JSON.stringify({ Critical: 2, High: 0, Medium: 2, Low: 1, None: 0 })"}],"hint":"prioritise: [...findings].sort((a, b) => b.score - a.score || Number(b.internet) - Number(a.internet) || a.title.localeCompare(b.title)).map(f => ({ title: f.title, score: f.score, severity: severity(f.score) }))"}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-logs$cdm$, $cdm${"title":"The blue-team view: spotting attacks in logs","kind":"code","task":"Write parseLine and detect.","hint":"parseLine: const m = /^(\\S+) \\[[^\\]]+\\] \"\\w+ (\\S+)\" (\\d{3}) \"([^\"]*)\"$/.exec(line); if (!m) return null. detect: group parsed lines by ip in an object (keep an array of IPs for order).","body":"## Every test leaves footprints\n\nDefenders (the **blue team**) watch logs for the same activity testers (the **red team**) create. Knowing both sides makes you better at each, and many careers start in the Security Operations Centre (SOC).\n\nA web server access log line typically records the client IP, time, request, status code and user agent:\n\n```text\n203.0.113.7 [2026-11-20T10:01:03Z] \"GET /wp-login.php\" 404 \"sqlmap/1.7\"\n```\n\nPatterns that matter:\n\n- **Brute force**: many `401` (unauthorised) responses to a login page from one IP in a short time.\n- **Directory scanning / probing**: many `404` (not found) responses from one IP, often for `/wp-admin`, `/.env`, `/.git/config`, `/phpmyadmin`.\n- **Known tool user agents**: scanners often announce themselves (`sqlmap`, `nikto`, `nmap`, `masscan`), though real attackers can change this.\n- **Sensitive paths**: requests for `/.env` or `/.git` show someone hunting for leaked secrets.\n\nResponses: rate-limit or block the IP, check whether any request **succeeded** (a `200` after many `401`s is an alarm), and make sure those files are never served.\n\n## Your task\n\nLog lines look like the example above. Write:\n\n1. `parseLine(line)`: `{ ip, path, status, agent }` (status as a number), or `null` if the line does not match.\n2. `detect(lines, limit)`: return alerts as strings, in this order per IP (IPs in order of first appearance):\n   - `\"IP brute force: N failed logins\"` if more than `limit` responses with status 401\n   - `\"IP scanning: N not-found requests\"` if more than `limit` responses with status 404\n   - `\"IP scanner tool: AGENT\"` (once per IP) if the agent contains sqlmap, nikto, nmap or masscan (any case)\n   - `\"IP asked for secrets: PATH\"` (once per IP, the first such path) if a path starts with `/.env` or `/.git`","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":6}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-logs$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-logs","title":"The blue-team view: spotting attacks in logs","minutes":25,"kind":"code","outline":"What scans, brute force and probing look like in web server logs, and build a simple detector.","body":"## Every test leaves footprints\n\nDefenders (the **blue team**) watch logs for the same activity testers (the **red team**) create. Knowing both sides makes you better at each, and many careers start in the Security Operations Centre (SOC).\n\nA web server access log line typically records the client IP, time, request, status code and user agent:\n\n```text\n203.0.113.7 [2026-11-20T10:01:03Z] \"GET /wp-login.php\" 404 \"sqlmap/1.7\"\n```\n\nPatterns that matter:\n\n- **Brute force**: many `401` (unauthorised) responses to a login page from one IP in a short time.\n- **Directory scanning / probing**: many `404` (not found) responses from one IP, often for `/wp-admin`, `/.env`, `/.git/config`, `/phpmyadmin`.\n- **Known tool user agents**: scanners often announce themselves (`sqlmap`, `nikto`, `nmap`, `masscan`), though real attackers can change this.\n- **Sensitive paths**: requests for `/.env` or `/.git` show someone hunting for leaked secrets.\n\nResponses: rate-limit or block the IP, check whether any request **succeeded** (a `200` after many `401`s is an alarm), and make sure those files are never served.\n\n## Your task\n\nLog lines look like the example above. Write:\n\n1. `parseLine(line)`: `{ ip, path, status, agent }` (status as a number), or `null` if the line does not match.\n2. `detect(lines, limit)`: return alerts as strings, in this order per IP (IPs in order of first appearance):\n   - `\"IP brute force: N failed logins\"` if more than `limit` responses with status 401\n   - `\"IP scanning: N not-found requests\"` if more than `limit` responses with status 404\n   - `\"IP scanner tool: AGENT\"` (once per IP) if the agent contains sqlmap, nikto, nmap or masscan (any case)\n   - `\"IP asked for secrets: PATH\"` (once per IP, the first such path) if a path starts with `/.env` or `/.git`","task":"Write parseLine and detect.","starter":"<script>\n  const LOG = [\n    '203.0.113.7 [2026-11-20T10:01:03Z] \"GET /wp-login.php\" 404 \"sqlmap/1.7\"',\n    '203.0.113.7 [2026-11-20T10:01:04Z] \"GET /.env\" 404 \"sqlmap/1.7\"',\n    '203.0.113.7 [2026-11-20T10:01:05Z] \"GET /admin\" 404 \"sqlmap/1.7\"',\n    '198.51.100.4 [2026-11-20T10:02:00Z] \"POST /login\" 401 \"Mozilla/5.0\"',\n    '198.51.100.4 [2026-11-20T10:02:01Z] \"POST /login\" 401 \"Mozilla/5.0\"',\n    '198.51.100.4 [2026-11-20T10:02:02Z] \"POST /login\" 401 \"Mozilla/5.0\"',\n    '198.51.100.4 [2026-11-20T10:02:03Z] \"POST /login\" 200 \"Mozilla/5.0\"',\n    '192.0.2.50 [2026-11-20T10:03:00Z] \"GET /\" 200 \"Mozilla/5.0\"',\n    'garbage line',\n  ]\n  function parseLine(line) {\n  }\n  function detect(lines, limit) {\n  }\n</script>\n","checks":[{"label":"parses a line","test":"const p = parseLine(LOG[0]); return p.ip === '203.0.113.7' && p.path === '/wp-login.php' && p.status === 404 && p.agent === 'sqlmap/1.7'"},{"label":"bad lines are null","test":"return parseLine('garbage line') === null"},{"label":"brute force found","test":"return detect(LOG, 2).includes('198.51.100.4 brute force: 3 failed logins')"},{"label":"scanning, tools and secret hunting found","test":"const d = detect(LOG, 2); return d.includes('203.0.113.7 scanning: 3 not-found requests') && d.includes('203.0.113.7 scanner tool: sqlmap/1.7') && d.includes('203.0.113.7 asked for secrets: /.env')"},{"label":"normal visitors raise nothing; order is per IP","test":"const d = detect(LOG, 2); return !d.some(x => x.startsWith('192.0.2.50')) && d.length === 4 && d[0].startsWith('203.0.113.7 scanning')"}],"hint":"parseLine: const m = /^(\\S+) \\[[^\\]]+\\] \"\\w+ (\\S+)\" (\\d{3}) \"([^\"]*)\"$/.exec(line); if (!m) return null. detect: group parsed lines by ip in an object (keep an array of IPs for order)."}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-osint$cdm$, $cdm${"title":"Passive reconnaissance and OSINT, within scope","kind":"read","task":null,"hint":null,"body":"## Looking before touching\n\nBefore any authorised test touches a system, testers study what the organisation has already made public. This is **passive reconnaissance**: collecting **open-source intelligence (OSINT)** without sending a single packet to the target's systems. Defenders do the same thing, because whatever a tester can find in an afternoon, a criminal can find too.\n\nThink of a security consultant hired to review a bank branch. Before entering, they walk around the outside: which doors face the street, where the cameras point, what is visible through the windows. They do not pick any locks.\n\n## Sources a tester reviews (for the organisation in scope)\n\n- **The organisation's own website**: staff pages, job adverts (which reveal the technology used: \"experience with Microsoft 365 and Fortinet firewalls\"), documents with hidden metadata (author names, software versions).\n- **DNS records**: the public \"phone book\" of the domain. Subdomains such as `staging.`, `old.` or `vpn.` often point to forgotten, unpatched systems.\n- **Certificate transparency logs**: every public HTTPS certificate is recorded in open logs (searchable at sites like crt.sh), which list subdomains the organisation may have forgotten.\n- **Code repositories**: public code sometimes contains passwords, API keys or internal addresses committed by mistake.\n- **Breach notifications and leaked-password services** such as Have I Been Pwned, to see whether the organisation's email addresses appear in known breaches (never to use the leaked passwords).\n- **Social media and professional networks**: who works there, in which roles, and what they post. Useful for judging phishing risk.\n\n## The limits are strict\n\n- Only research the organisation that **authorised** the engagement, within the written scope.\n- Passive does not mean \"anything goes\". Do not log in with leaked credentials, do not trick staff, and do not access private accounts or groups by pretending to be someone.\n- Collect the minimum personal data needed, store it securely, and delete it at the end of the engagement. Data protection laws (NDPA in Nigeria, GDPR in Europe) apply to testers too.\n- Report exposed personal information carefully: the goal is to protect those people, not to embarrass them.\n\n## Turning findings into defence\n\nFor each finding, recommend a fix:\n\n| Finding | Fix |\n|---|---|\n| Forgotten `staging` subdomain running old software | Take it down or patch it; keep an asset inventory |\n| API key in a public repository | Revoke it immediately, then remove it and scan repositories automatically |\n| Staff emails in many breaches | Two-step sign-in for all, password manager rollout, phishing training |\n| Job adverts listing exact firewall versions | Describe skills, not exact versions |\n| Documents with author and software metadata | Strip metadata before publishing |\n\n## Attack surface management\n\nMature organisations run this reconnaissance **on themselves**, continuously: monitoring new certificates, DNS changes and leaked credentials, so they find exposure before attackers do.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":7}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-osint$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-osint","title":"Passive reconnaissance and OSINT, within scope","minutes":30,"kind":"read","outline":"What public information reveals about an organisation, DNS and certificate records, staff exposure, and the legal and ethical limits.","body":"## Looking before touching\n\nBefore any authorised test touches a system, testers study what the organisation has already made public. This is **passive reconnaissance**: collecting **open-source intelligence (OSINT)** without sending a single packet to the target's systems. Defenders do the same thing, because whatever a tester can find in an afternoon, a criminal can find too.\n\nThink of a security consultant hired to review a bank branch. Before entering, they walk around the outside: which doors face the street, where the cameras point, what is visible through the windows. They do not pick any locks.\n\n## Sources a tester reviews (for the organisation in scope)\n\n- **The organisation's own website**: staff pages, job adverts (which reveal the technology used: \"experience with Microsoft 365 and Fortinet firewalls\"), documents with hidden metadata (author names, software versions).\n- **DNS records**: the public \"phone book\" of the domain. Subdomains such as `staging.`, `old.` or `vpn.` often point to forgotten, unpatched systems.\n- **Certificate transparency logs**: every public HTTPS certificate is recorded in open logs (searchable at sites like crt.sh), which list subdomains the organisation may have forgotten.\n- **Code repositories**: public code sometimes contains passwords, API keys or internal addresses committed by mistake.\n- **Breach notifications and leaked-password services** such as Have I Been Pwned, to see whether the organisation's email addresses appear in known breaches (never to use the leaked passwords).\n- **Social media and professional networks**: who works there, in which roles, and what they post. Useful for judging phishing risk.\n\n## The limits are strict\n\n- Only research the organisation that **authorised** the engagement, within the written scope.\n- Passive does not mean \"anything goes\". Do not log in with leaked credentials, do not trick staff, and do not access private accounts or groups by pretending to be someone.\n- Collect the minimum personal data needed, store it securely, and delete it at the end of the engagement. Data protection laws (NDPA in Nigeria, GDPR in Europe) apply to testers too.\n- Report exposed personal information carefully: the goal is to protect those people, not to embarrass them.\n\n## Turning findings into defence\n\nFor each finding, recommend a fix:\n\n| Finding | Fix |\n|---|---|\n| Forgotten `staging` subdomain running old software | Take it down or patch it; keep an asset inventory |\n| API key in a public repository | Revoke it immediately, then remove it and scan repositories automatically |\n| Staff emails in many breaches | Two-step sign-in for all, password manager rollout, phishing training |\n| Job adverts listing exact firewall versions | Describe skills, not exact versions |\n| Documents with author and software metadata | Strip metadata before publishing |\n\n## Attack surface management\n\nMature organisations run this reconnaissance **on themselves**, continuously: monitoring new certificates, DNS changes and leaked credentials, so they find exposure before attackers do.","quiz":[{"q":"Passive reconnaissance means…","options":["Scanning every port quickly","Gathering public information without touching the target's systems","Logging in with leaked passwords"],"answer":1,"why":"No packets are sent to the target."},{"q":"Certificate transparency logs can reveal…","options":["Users' passwords","Subdomains, including forgotten ones","Bank balances"],"answer":1,"why":"Every public certificate is logged openly."},{"q":"You find working staff passwords in a public breach dump. You should…","options":["Test them on the company's email","Not use them; report the exposure so the passwords are reset","Sell them"],"answer":1,"why":"Using leaked credentials is outside any normal scope and often illegal."},{"q":"A public repository contains a live API key. The first fix is to…","options":["Delete the file only","Revoke the key immediately, then clean the repository","Make the repository private and keep the key"],"answer":1,"why":"Assume it was already copied."}]}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-authz$cdm$, $cdm${"title":"Broken access control: finding and fixing IDOR","kind":"code","task":"Write canView, canEdit, canRefund and fetchInvoice.","hint":"Start canView with: if (!user || !invoice || !ROLES.includes(user.role)) return false; return user.company === invoice.company. Build canEdit and canRefund on top of canView.","body":"## The hotel key that opens every room\n\nImagine a hotel where your key card opens room 214. Out of curiosity you try room 215, and it opens too. The lock checked that you had *a* key, not that it was *your* room. That is **broken access control**, and it is number one on the **OWASP Top 10**, the industry's list of the most serious web application risks.\n\n## IDOR: changing a number in the address\n\nA very common form is the **insecure direct object reference (IDOR)**:\n\n```\nhttps://shop.example/invoices/1042   ← your invoice\nhttps://shop.example/invoices/1043   ← someone else's invoice, if the server does not check\n```\n\nThe app authenticated you (it knows who you are) but did not authorise this request (check that invoice 1043 is yours). Real incidents have exposed millions of records this way: medical results, bank statements, ID documents.\n\n## How a tester checks (on an authorised target)\n\n1. Create **two test accounts** in the same app, user A and user B.\n2. As A, note the IDs of A's objects (orders, invoices, messages, files).\n3. As B, request A's objects by ID. Try reading, editing and deleting.\n4. Check **functions** too: can a normal user call admin actions, like `POST /api/users/7/role`, by sending the request directly, even though the button is hidden?\n5. Check every channel: web pages, the mobile app's API, file download links, exports.\n\nTesters only use their own test accounts and test data, never real customers' records. If real data is exposed by accident, they stop, record the minimum evidence, and report it at once.\n\n## The fix: check on the server, every time\n\n- For every request, the **server** decides: *is this user allowed to do this action on this object?* Hiding a button is not security.\n- **Deny by default**: if no rule allows it, refuse.\n- Check **ownership** (the invoice belongs to this user) or **membership** (the user belongs to the company that owns it) and **role** (only managers may refund).\n- Use the database to enforce it where possible. In PostgreSQL and Supabase, **row level security** policies make the database itself refuse rows a user may not see, even if the app has a bug.\n- Return the **same** response for \"does not exist\" and \"not yours\" (often 404), so attackers cannot learn which IDs exist.\n- Random, unguessable IDs (UUIDs) help, but they do not replace the check.\n\n## Your task\n\nWrite the access check for an invoicing app.\n\n- Users look like `{ id, company, role }` where role is `\"owner\"`, `\"manager\"`, `\"staff\"` or `\"auditor\"`.\n- Invoices look like `{ id, company, createdBy }`.\n\n1. `canView(user, invoice)`: only users of the **same company** may view. (An unknown role may not.)\n2. `canEdit(user, invoice)`: same company, and either owner or manager, or staff editing an invoice **they created**. Auditors never edit.\n3. `canRefund(user, invoice)`: same company and owner or manager only.\n4. `fetchInvoice(user, id, db)`: `db` is a list of invoices. Return `{ status: 200, invoice }` when allowed to view; otherwise `{ status: 404 }`, the **same** for missing and forbidden.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":8}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-authz$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-authz","title":"Broken access control: finding and fixing IDOR","minutes":35,"kind":"code","outline":"Why broken access control tops the OWASP Top 10, how testers check object-level and function-level permissions, and writing the fix.","body":"## The hotel key that opens every room\n\nImagine a hotel where your key card opens room 214. Out of curiosity you try room 215, and it opens too. The lock checked that you had *a* key, not that it was *your* room. That is **broken access control**, and it is number one on the **OWASP Top 10**, the industry's list of the most serious web application risks.\n\n## IDOR: changing a number in the address\n\nA very common form is the **insecure direct object reference (IDOR)**:\n\n```\nhttps://shop.example/invoices/1042   ← your invoice\nhttps://shop.example/invoices/1043   ← someone else's invoice, if the server does not check\n```\n\nThe app authenticated you (it knows who you are) but did not authorise this request (check that invoice 1043 is yours). Real incidents have exposed millions of records this way: medical results, bank statements, ID documents.\n\n## How a tester checks (on an authorised target)\n\n1. Create **two test accounts** in the same app, user A and user B.\n2. As A, note the IDs of A's objects (orders, invoices, messages, files).\n3. As B, request A's objects by ID. Try reading, editing and deleting.\n4. Check **functions** too: can a normal user call admin actions, like `POST /api/users/7/role`, by sending the request directly, even though the button is hidden?\n5. Check every channel: web pages, the mobile app's API, file download links, exports.\n\nTesters only use their own test accounts and test data, never real customers' records. If real data is exposed by accident, they stop, record the minimum evidence, and report it at once.\n\n## The fix: check on the server, every time\n\n- For every request, the **server** decides: *is this user allowed to do this action on this object?* Hiding a button is not security.\n- **Deny by default**: if no rule allows it, refuse.\n- Check **ownership** (the invoice belongs to this user) or **membership** (the user belongs to the company that owns it) and **role** (only managers may refund).\n- Use the database to enforce it where possible. In PostgreSQL and Supabase, **row level security** policies make the database itself refuse rows a user may not see, even if the app has a bug.\n- Return the **same** response for \"does not exist\" and \"not yours\" (often 404), so attackers cannot learn which IDs exist.\n- Random, unguessable IDs (UUIDs) help, but they do not replace the check.\n\n## Your task\n\nWrite the access check for an invoicing app.\n\n- Users look like `{ id, company, role }` where role is `\"owner\"`, `\"manager\"`, `\"staff\"` or `\"auditor\"`.\n- Invoices look like `{ id, company, createdBy }`.\n\n1. `canView(user, invoice)`: only users of the **same company** may view. (An unknown role may not.)\n2. `canEdit(user, invoice)`: same company, and either owner or manager, or staff editing an invoice **they created**. Auditors never edit.\n3. `canRefund(user, invoice)`: same company and owner or manager only.\n4. `fetchInvoice(user, id, db)`: `db` is a list of invoices. Return `{ status: 200, invoice }` when allowed to view; otherwise `{ status: 404 }`, the **same** for missing and forbidden.","task":"Write canView, canEdit, canRefund and fetchInvoice.","starter":"<script>\n  const ROLES = ['owner', 'manager', 'staff', 'auditor']\n  function canView(user, invoice) {\n    return true\n  }\n  function canEdit(user, invoice) {\n    return true\n  }\n  function canRefund(user, invoice) {\n    return true\n  }\n  function fetchInvoice(user, id, db) {\n    const invoice = db.find((i) => i.id === id)\n    return { status: 200, invoice }\n  }\n</script>\n","checks":[{"label":"other companies cannot view","test":"const inv = { id: 1, company: 'A', createdBy: 'u1' }; return canView({ id: 'u1', company: 'A', role: 'staff' }, inv) && !canView({ id: 'x', company: 'B', role: 'owner' }, inv) && !canView({ id: 'y', company: 'A', role: 'intern' }, inv)"},{"label":"edit rules by role and creator","test":"const inv = { id: 1, company: 'A', createdBy: 'u1' }; return canEdit({ id: 'm', company: 'A', role: 'manager' }, inv) && canEdit({ id: 'u1', company: 'A', role: 'staff' }, inv) && !canEdit({ id: 'u2', company: 'A', role: 'staff' }, inv) && !canEdit({ id: 'au', company: 'A', role: 'auditor' }, inv) && !canEdit({ id: 'o', company: 'B', role: 'owner' }, inv)"},{"label":"refunds for owners and managers only","test":"const inv = { id: 1, company: 'A', createdBy: 'u1' }; return canRefund({ id: 'o', company: 'A', role: 'owner' }, inv) && !canRefund({ id: 'u1', company: 'A', role: 'staff' }, inv) && !canRefund({ id: 'o', company: 'B', role: 'owner' }, inv)"},{"label":"IDOR blocked with the same 404","test":"const db = [{ id: 1042, company: 'A', createdBy: 'u1' }, { id: 1043, company: 'B', createdBy: 'u9' }]; const me = { id: 'u1', company: 'A', role: 'staff' }; const a = fetchInvoice(me, 1042, db), b = fetchInvoice(me, 1043, db), c = fetchInvoice(me, 9999, db); return a.status === 200 && a.invoice.id === 1042 && b.status === 404 && !b.invoice && JSON.stringify(b) === JSON.stringify(c)"}],"hint":"Start canView with: if (!user || !invoice || !ROLES.includes(user.role)) return false; return user.company === invoice.company. Build canEdit and canRefund on top of canView."}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-misconfig$cdm$, $cdm${"title":"Security misconfiguration and weak crypto","kind":"code","task":"Write review and sortFindings.","hint":"const RANK = { critical: 0, high: 1, medium: 2, low: 3 }; sort with (a, b) => RANK[a.severity] - RANK[b.severity] (Array sort is stable in modern browsers).","body":"## Leaving the keys in the door\n\nMany breaches need no clever hacking at all. A database left open to the internet with no password, an admin panel at `/admin` with the default login `admin / admin`, a server showing full error messages with file paths and passwords: these are **security misconfigurations**, a permanent member of the OWASP Top 10. It is like buying a strong lock and leaving the key in it.\n\n## What testers look for (on authorised systems)\n\n- **Default or blank credentials** on routers, cameras, databases, admin panels and CMS installs.\n- **Debug or development mode** in production, which shows stack traces, environment variables and internal paths.\n- **Directory listing**: a web server showing every file in a folder, including backups like `db_backup.sql`.\n- **Unnecessary services and sample apps** left installed.\n- **Admin interfaces open to the whole internet** instead of a VPN or allow-list.\n- **Overly permissive CORS** (`Access-Control-Allow-Origin: *` together with credentials).\n- **Cloud storage buckets** set to public by mistake.\n- **Missing security headers** (the Cybersecurity course covers these).\n\n## Weak cryptography\n\n- **Old TLS versions**: TLS 1.0 and 1.1 are retired; servers should accept only **TLS 1.2 and 1.3**.\n- **Weak password hashing**: MD5 or SHA-1, or plain unsalted hashes, can be cracked fast. Passwords need slow, salted algorithms built for the job: **bcrypt**, **scrypt** or **Argon2**.\n- **Hard-coded secrets** in code or config files committed to repositories.\n- **Home-made encryption**: never invent your own; use well-reviewed libraries.\n\n## Why it happens\n\nSystems are set up in a hurry, defaults are kept \"for now\", a test server becomes production, or settings drift over time as different people make changes. The fix is a process, not a one-off clean-up:\n\n- A **hardening checklist** or baseline (CIS Benchmarks exist for most systems).\n- **Infrastructure as code** so settings are reviewed and repeatable (the Cloud course covers this).\n- **Automated scanning** of configurations in the CI pipeline.\n- Regular reviews and an up-to-date asset list.\n\n## Your task\n\nWrite a configuration review that turns a server's settings into findings with severities.\n\n`config` looks like `{ debug, directoryListing, adminPublic, tlsVersions, passwordHash, users: [{ name, password }] }`.\n\n`review(config)` returns a list of `{ issue, severity }` with these rules:\n\n| Condition | issue | severity |\n|---|---|---|\n| a user whose password is in `DEFAULTS` (or empty) | `default password for NAME` | `critical` |\n| `debug` is true | `debug mode on` | `high` |\n| `adminPublic` is true | `admin panel public` | `high` |\n| `tlsVersions` includes `\"1.0\"` or `\"1.1\"` | `old tls` | `medium` |\n| `passwordHash` is not bcrypt, scrypt or argon2 | `weak password hashing` | `high` |\n| `directoryListing` is true | `directory listing` | `medium` |\n\nThen `sortFindings(findings)` orders them critical, high, medium, low (keeping the original order within a severity).","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":9}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-misconfig$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-misconfig","title":"Security misconfiguration and weak crypto","minutes":35,"kind":"code","outline":"Default passwords, debug modes, directory listing, old TLS, exposed admin panels, and coding a configuration review.","body":"## Leaving the keys in the door\n\nMany breaches need no clever hacking at all. A database left open to the internet with no password, an admin panel at `/admin` with the default login `admin / admin`, a server showing full error messages with file paths and passwords: these are **security misconfigurations**, a permanent member of the OWASP Top 10. It is like buying a strong lock and leaving the key in it.\n\n## What testers look for (on authorised systems)\n\n- **Default or blank credentials** on routers, cameras, databases, admin panels and CMS installs.\n- **Debug or development mode** in production, which shows stack traces, environment variables and internal paths.\n- **Directory listing**: a web server showing every file in a folder, including backups like `db_backup.sql`.\n- **Unnecessary services and sample apps** left installed.\n- **Admin interfaces open to the whole internet** instead of a VPN or allow-list.\n- **Overly permissive CORS** (`Access-Control-Allow-Origin: *` together with credentials).\n- **Cloud storage buckets** set to public by mistake.\n- **Missing security headers** (the Cybersecurity course covers these).\n\n## Weak cryptography\n\n- **Old TLS versions**: TLS 1.0 and 1.1 are retired; servers should accept only **TLS 1.2 and 1.3**.\n- **Weak password hashing**: MD5 or SHA-1, or plain unsalted hashes, can be cracked fast. Passwords need slow, salted algorithms built for the job: **bcrypt**, **scrypt** or **Argon2**.\n- **Hard-coded secrets** in code or config files committed to repositories.\n- **Home-made encryption**: never invent your own; use well-reviewed libraries.\n\n## Why it happens\n\nSystems are set up in a hurry, defaults are kept \"for now\", a test server becomes production, or settings drift over time as different people make changes. The fix is a process, not a one-off clean-up:\n\n- A **hardening checklist** or baseline (CIS Benchmarks exist for most systems).\n- **Infrastructure as code** so settings are reviewed and repeatable (the Cloud course covers this).\n- **Automated scanning** of configurations in the CI pipeline.\n- Regular reviews and an up-to-date asset list.\n\n## Your task\n\nWrite a configuration review that turns a server's settings into findings with severities.\n\n`config` looks like `{ debug, directoryListing, adminPublic, tlsVersions, passwordHash, users: [{ name, password }] }`.\n\n`review(config)` returns a list of `{ issue, severity }` with these rules:\n\n| Condition | issue | severity |\n|---|---|---|\n| a user whose password is in `DEFAULTS` (or empty) | `default password for NAME` | `critical` |\n| `debug` is true | `debug mode on` | `high` |\n| `adminPublic` is true | `admin panel public` | `high` |\n| `tlsVersions` includes `\"1.0\"` or `\"1.1\"` | `old tls` | `medium` |\n| `passwordHash` is not bcrypt, scrypt or argon2 | `weak password hashing` | `high` |\n| `directoryListing` is true | `directory listing` | `medium` |\n\nThen `sortFindings(findings)` orders them critical, high, medium, low (keeping the original order within a severity).","task":"Write review and sortFindings.","starter":"<script>\n  const DEFAULTS = ['admin', 'password', '123456', 'root', 'changeme', 'default']\n  function review(config) {\n    return []\n  }\n  function sortFindings(findings) {\n    return findings\n  }\n</script>\n","checks":[{"label":"default and empty passwords are critical","test":"const f = review({ users: [{ name: 'admin', password: 'admin' }, { name: 'cam', password: '' }, { name: 'ada', password: 'x9!Lq-27-Blue' }], tlsVersions: ['1.2'], passwordHash: 'argon2' }); return f.length === 2 && f.every((x) => x.severity === 'critical') && f[0].issue === 'default password for admin' && f[1].issue === 'default password for cam'"},{"label":"debug, admin, tls and listing found","test":"const f = review({ debug: true, adminPublic: true, directoryListing: true, tlsVersions: ['1.0', '1.2'], passwordHash: 'bcrypt', users: [] }); const has = (i, s) => f.some((x) => x.issue === i && x.severity === s); return f.length === 4 && has('debug mode on', 'high') && has('admin panel public', 'high') && has('old tls', 'medium') && has('directory listing', 'medium')"},{"label":"weak hashing flagged","test":"const ok = ['bcrypt', 'scrypt', 'argon2'].every((h) => review({ passwordHash: h, tlsVersions: [], users: [] }).length === 0); return ok && review({ passwordHash: 'md5', tlsVersions: [], users: [] })[0].issue === 'weak password hashing'"},{"label":"findings sorted by severity","test":"const s = sortFindings([{ issue: 'a', severity: 'medium' }, { issue: 'b', severity: 'critical' }, { issue: 'c', severity: 'high' }, { issue: 'd', severity: 'low' }, { issue: 'e', severity: 'high' }]); return s.map((x) => x.issue).join('') === 'bcead'"}],"hint":"const RANK = { critical: 0, high: 1, medium: 2, low: 3 }; sort with (a, b) => RANK[a.severity] - RANK[b.severity] (Array sort is stable in modern browsers)."}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-labs$cdm$, $cdm${"title":"Practising legally: labs, CTFs and bug bounties","kind":"read","task":null,"hint":null,"body":"## Where to practise without breaking the law\n\nA medical student practises on models and supervised patients, never on strangers in the street. Security learners need the same: places built for practice, where attacking is **allowed**. Testing systems you do not own or have written permission to test is a crime in most countries (in Nigeria under the Cybercrimes Act 2015, in the UK under the Computer Misuse Act, in the US under the CFAA), even \"just to look\".\n\n## A home lab\n\nBuild a small lab on your own computer:\n\n- **Virtual machines** with VirtualBox, VMware or Hyper-V, or **containers** with Docker, on a private network that cannot reach the internet or your home devices.\n- **Deliberately vulnerable applications**, made for practice:\n  - **OWASP Juice Shop**: a modern web shop full of the OWASP Top 10 flaws, with a built-in score board.\n  - **DVWA** (Damn Vulnerable Web Application): classic web flaws at adjustable difficulty.\n  - **OWASP WebGoat**: guided lessons with explanations.\n  - **Metasploitable**: a deliberately weak Linux machine for practising scanning and service testing.\n- Take **snapshots** so you can reset everything after each exercise.\n\n## Online platforms\n\n- **TryHackMe**: guided, browser-based rooms for beginners, with learning paths.\n- **Hack The Box**: harder machines and an Academy with structured modules.\n- **PortSwigger Web Security Academy**: free, excellent labs for every web vulnerability, from the makers of Burp Suite.\n- **picoCTF** and other **capture-the-flag (CTF)** competitions: puzzles where you find a hidden \"flag\" string, in teams or alone. CTFs teach creativity and persistence.\n\nRead each platform's rules: attack only the machines they give you.\n\n## Bug bounty programmes\n\nMany organisations invite the public to find and report security bugs, and pay rewards. Platforms such as **HackerOne**, **Bugcrowd** and **Intigriti** host these programmes.\n\n- Read the **policy** first: what is in scope, what is out of scope (often denial-of-service, social engineering and physical attacks), and what testing is allowed.\n- Use your **own test accounts**; never access or change other users' data. If you see real personal data, stop and report.\n- Write clear reports: steps to reproduce, impact, and a suggested fix.\n- Follow **coordinated disclosure**: give the organisation time to fix before discussing publicly.\n- Organisations without a programme may still have a `security.txt` file or a vulnerability disclosure policy explaining how to report safely.\n\n## Building a reputation and a career\n\n- Write up what you learn (for retired machines and solved labs only, as platforms require) in a blog or on GitHub.\n- Certifications employers recognise: CompTIA Security+ and PenTest+, eJPT, OSCP, and cloud security certificates.\n- Join local and online communities, attend security meetups and conferences, and help others learn.\n- Remember the blue team: understanding attacks makes you a far better defender, and defensive roles (SOC analyst, security engineer) are where most security jobs are.","practice":null,"track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":10}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-labs$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-labs","title":"Practising legally: labs, CTFs and bug bounties","minutes":25,"kind":"read","outline":"Building a home lab, deliberately vulnerable apps, capture-the-flag platforms, bug bounty rules and building a reputation.","body":"## Where to practise without breaking the law\n\nA medical student practises on models and supervised patients, never on strangers in the street. Security learners need the same: places built for practice, where attacking is **allowed**. Testing systems you do not own or have written permission to test is a crime in most countries (in Nigeria under the Cybercrimes Act 2015, in the UK under the Computer Misuse Act, in the US under the CFAA), even \"just to look\".\n\n## A home lab\n\nBuild a small lab on your own computer:\n\n- **Virtual machines** with VirtualBox, VMware or Hyper-V, or **containers** with Docker, on a private network that cannot reach the internet or your home devices.\n- **Deliberately vulnerable applications**, made for practice:\n  - **OWASP Juice Shop**: a modern web shop full of the OWASP Top 10 flaws, with a built-in score board.\n  - **DVWA** (Damn Vulnerable Web Application): classic web flaws at adjustable difficulty.\n  - **OWASP WebGoat**: guided lessons with explanations.\n  - **Metasploitable**: a deliberately weak Linux machine for practising scanning and service testing.\n- Take **snapshots** so you can reset everything after each exercise.\n\n## Online platforms\n\n- **TryHackMe**: guided, browser-based rooms for beginners, with learning paths.\n- **Hack The Box**: harder machines and an Academy with structured modules.\n- **PortSwigger Web Security Academy**: free, excellent labs for every web vulnerability, from the makers of Burp Suite.\n- **picoCTF** and other **capture-the-flag (CTF)** competitions: puzzles where you find a hidden \"flag\" string, in teams or alone. CTFs teach creativity and persistence.\n\nRead each platform's rules: attack only the machines they give you.\n\n## Bug bounty programmes\n\nMany organisations invite the public to find and report security bugs, and pay rewards. Platforms such as **HackerOne**, **Bugcrowd** and **Intigriti** host these programmes.\n\n- Read the **policy** first: what is in scope, what is out of scope (often denial-of-service, social engineering and physical attacks), and what testing is allowed.\n- Use your **own test accounts**; never access or change other users' data. If you see real personal data, stop and report.\n- Write clear reports: steps to reproduce, impact, and a suggested fix.\n- Follow **coordinated disclosure**: give the organisation time to fix before discussing publicly.\n- Organisations without a programme may still have a `security.txt` file or a vulnerability disclosure policy explaining how to report safely.\n\n## Building a reputation and a career\n\n- Write up what you learn (for retired machines and solved labs only, as platforms require) in a blog or on GitHub.\n- Certifications employers recognise: CompTIA Security+ and PenTest+, eJPT, OSCP, and cloud security certificates.\n- Join local and online communities, attend security meetups and conferences, and help others learn.\n- Remember the blue team: understanding attacks makes you a far better defender, and defensive roles (SOC analyst, security engineer) are where most security jobs are.","quiz":[{"q":"Testing a company's website without written permission \"just to look\" is…","options":["Fine if nothing is damaged","Illegal in most countries","Allowed for students"],"answer":1,"why":"Authorisation is what makes testing legal."},{"q":"OWASP Juice Shop and DVWA are…","options":["Real banks","Deliberately vulnerable apps built for practice","Antivirus programs"],"answer":1,"why":"They exist so you can practise legally."},{"q":"In a bug bounty, you notice other customers' personal data. You should…","options":["Download it as proof","Stop, keep minimal evidence and report it","Post it online"],"answer":1,"why":"Protect the people; report responsibly."},{"q":"Before testing a bug bounty target you must…","options":["Read the policy and scope","Ask a friend","Scan everything at full speed"],"answer":0,"why":"The policy defines what is allowed."}]}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.lesson_meta (id, meta) values ($cdm$ethhack-report$cdm$, $cdm${"title":"Reporting, disclosure and your security career","kind":"prompt","task":null,"hint":null,"body":"## A finding clients can act on\n\nEach finding in a professional report has:\n\n1. **Title**: short and specific. *\"SQL injection in /login lets anyone sign in as any user\"*\n2. **Severity**: CVSS score and band, plus business impact in plain words\n3. **Affected assets**: exact addresses, parameters, versions\n4. **Description**: what is wrong, in language a manager understands\n5. **Evidence**: steps to reproduce at a safe level, screenshots, request and response (with real personal data **removed**)\n6. **Recommendation**: the fix (parameterised queries, update to version X, turn on HttpOnly), and how to verify it\n7. **References**: OWASP, CWE number, vendor advisory\n\nThe report opens with an **executive summary**: overall risk, the top 3 issues, and what to do first. It ends with what was **not** tested.\n\n## Responsible disclosure in practice\n\n- Report through the official channel (security.txt, a security@ email, the bug bounty page)\n- Include enough to reproduce, nothing more; never threaten or demand payment\n- Agree a timeline; follow up politely\n- In a bounty programme, follow its rules exactly; duplicates and out-of-scope reports are normal, learn and move on\n\n## Building a career\n\n- **Foundations**: networking (TCP/IP, DNS, HTTP), Linux command line, one scripting language (Python or JavaScript), and web basics. Your CDM Studio courses in Cybersecurity, Cloud and Web cover much of this.\n- **Hands-on practice**: TryHackMe paths, Hack The Box, PortSwigger Academy, CTFs. Write up what you learn (without spoiling live challenges).\n- **Certifications employers ask for**: CompTIA Security+ and PenTest+, **eJPT** (entry, hands-on), **PNPT**, **CEH**, and the respected **OSCP** (hard, practical exam). Cloud and web certifications follow (OSWE, BSCP).\n- **Jobs**: SOC analyst and vulnerability management roles are common entry points; junior penetration tester after hands-on certifications; freelance bug bounty alongside.\n- **Reputation is everything**: in security, trust is the job. One illegal \"test\" can end a career before it starts.\n\n## Practise\n\nAsk the tutor to help you turn a lab finding into a professional write-up.","practice":"Describe a finding from a legal practice lab (for example: \"In OWASP Juice Shop, the product search box showed a database error when I typed a single quote\"). Ask the AI to help you write it up as a professional finding with title, severity and business impact, affected asset, description, safe reproduction steps, recommendation and references. Then ask it to write a 3-sentence executive summary.","track":"ethhack","track_title":"Ethical hacking and penetration testing","paid":true,"order":11}$cdm$::jsonb) on conflict (id) do update set meta = excluded.meta, updated_at = now();
insert into public.lesson_content (id, track, body) values ($cdm$ethhack-report$cdm$, $cdm$ethhack$cdm$, $cdm${"id":"ethhack-report","title":"Reporting, disclosure and your security career","minutes":20,"kind":"prompt","outline":"Write findings clients act on, report bugs responsibly, and plan certifications and a portfolio.","body":"## A finding clients can act on\n\nEach finding in a professional report has:\n\n1. **Title**: short and specific. *\"SQL injection in /login lets anyone sign in as any user\"*\n2. **Severity**: CVSS score and band, plus business impact in plain words\n3. **Affected assets**: exact addresses, parameters, versions\n4. **Description**: what is wrong, in language a manager understands\n5. **Evidence**: steps to reproduce at a safe level, screenshots, request and response (with real personal data **removed**)\n6. **Recommendation**: the fix (parameterised queries, update to version X, turn on HttpOnly), and how to verify it\n7. **References**: OWASP, CWE number, vendor advisory\n\nThe report opens with an **executive summary**: overall risk, the top 3 issues, and what to do first. It ends with what was **not** tested.\n\n## Responsible disclosure in practice\n\n- Report through the official channel (security.txt, a security@ email, the bug bounty page)\n- Include enough to reproduce, nothing more; never threaten or demand payment\n- Agree a timeline; follow up politely\n- In a bounty programme, follow its rules exactly; duplicates and out-of-scope reports are normal, learn and move on\n\n## Building a career\n\n- **Foundations**: networking (TCP/IP, DNS, HTTP), Linux command line, one scripting language (Python or JavaScript), and web basics. Your CDM Studio courses in Cybersecurity, Cloud and Web cover much of this.\n- **Hands-on practice**: TryHackMe paths, Hack The Box, PortSwigger Academy, CTFs. Write up what you learn (without spoiling live challenges).\n- **Certifications employers ask for**: CompTIA Security+ and PenTest+, **eJPT** (entry, hands-on), **PNPT**, **CEH**, and the respected **OSCP** (hard, practical exam). Cloud and web certifications follow (OSWE, BSCP).\n- **Jobs**: SOC analyst and vulnerability management roles are common entry points; junior penetration tester after hands-on certifications; freelance bug bounty alongside.\n- **Reputation is everything**: in security, trust is the job. One illegal \"test\" can end a career before it starts.\n\n## Practise\n\nAsk the tutor to help you turn a lab finding into a professional write-up.","practice":"Describe a finding from a legal practice lab (for example: \"In OWASP Juice Shop, the product search box showed a database error when I typed a single quote\"). Ask the AI to help you write it up as a professional finding with title, severity and business impact, affected asset, description, safe reproduction steps, recommendation and references. Then ask it to write a 3-sentence executive summary."}$cdm$::jsonb) on conflict (id) do update set body = excluded.body, track = excluded.track, updated_at = now();
insert into public.course_projects (track, title, brief, lang, rubric, pass_pct) values ($cdm$ethhack$cdm$, $cdm$Penetration test report on a practice target$cdm$, $cdm$Run an authorised test against a **practice target you are allowed to attack**: OWASP Juice Shop or DVWA running in your own lab, a TryHackMe or Hack The Box machine (following their rules on write-ups), or an app **you built yourself**. Do not test any system you do not own or have written permission to test.
insert into public.exam_questions (track, n, question, options, answer) values ($cdm$ethhack$cdm$, 1, $cdm$What separates ethical hacking from a crime?$cdm$, $cdm$["Good intentions","Written permission from the system owner, within an agreed scope","Using well-known tools","Not changing any data"]$cdm$::jsonb, 1);
