insert into public.exam_questions (track, n, question, options, answer) values ($cdm$ethhack$cdm$, 11, $cdm$Anyone who has a JWT can…$cdm$, $cdm$["Change its claims without detection","Decode and read its payload","Never read it","Make the server accept \"alg: none\" safely"]$cdm$::jsonb, 1);
insert into public.exam_questions (track, n, question, options, answer) values ($cdm$ethhack$cdm$, 12, $cdm$A server receives a JWT with "alg": "none". It should…$cdm$, $cdm$["Accept it if exp is valid","Refuse it","Accept it for admins only","Log the user in as a guest"]$cdm$::jsonb, 1);
insert into public.exam_questions (track, n, question, options, answer) values ($cdm$ethhack$cdm$, 13, $cdm$Changing /invoices/105 to /invoices/106 shows another customer's invoice. This is…$cdm$, $cdm$["IDOR (broken access control)","Cross-site scripting","A strong design","Rate limiting"]$cdm$::jsonb, 0);
